"use client";import {useEffect,useState} from 'react'; const BASE=process.env.NEXT_PUBLIC_AGENT_BASE||'';
export default function Invoice(){ const [org,setOrg]=useState('default'); const [data,setData]=useState<any>(); async function load(){ const r=await fetch('/billing/invoice/preview',{headers:{'x-org-id':org}}); setData(await r.json()); }
return (<div className='max-w-3xl mx-auto py-8'>
  <h1 className='text-xl font-bold'>Invoice Preview</h1>
  <div className='flex gap-2 mt-2'>
    <input className='p-2 border rounded' value={org} onChange={e=>setOrg(e.target.value)} placeholder='org id'/>
    <button className='px-3 py-2 bg-black text-white rounded' onClick={load}>Load</button>
  </div>
  {data && <pre className='mt-3 text-xs bg-gray-50 p-3 rounded'>{JSON.stringify(data,null,2)}</pre>}
</div>);}
